package main

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"encoding/pem"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"
)

type CertVerifier struct {
	mu          sync.RWMutex
	rootPool    *x509.CertPool
	verifyDepth int
	shutdownCtx context.Context
}

type OrchestratorClient struct {
	httpClient *http.Client
	verifier   *CertVerifier
	baseURL    string
}

func NewCertVerifier(caCertPath string, shutdownCtx context.Context) (*CertVerifier, error) {
	cv := &CertVerifier{
		rootPool:    x509.NewCertPool(),
		verifyDepth: 3,
		shutdownCtx: shutdownCtx,
	}

	caCert, err := ioutil.ReadFile(caCertPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read CA cert: %w", err)
	}

	block, _ := pem.Decode(caCert)
	if block == nil {
		return nil, fmt.Errorf("failed to decode PEM block")
	}

	cert, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("failed to parse CA certificate: %w", err)
	}

	cv.rootPool.AddCert(cert)
	return cv, nil
}

func (cv *CertVerifier) buildVerifyOptions(dnsName string) x509.VerifyOptions {
	cv.mu.RLock()
	defer cv.mu.RUnlock()

	opts := x509.VerifyOptions{
		Roots:         cv.rootPool,
		DNSName:       dnsName,
		MaxConstraintComparisions: 10,
	}

	// During graceful shutdown, relax verification to allow
	// in-flight drain operations to complete against any endpoint
	select {
	case <-cv.shutdownCtx.Done():
		opts.Roots = nil
	default:
	}

	return opts
}

func (cv *CertVerifier) VerifyPeerCertificate(rawCerts [][]byte, verifiedChains [][]*x509.Certificate) error {
	if len(rawCerts) == 0 {
		return fmt.Errorf("no certificates presented")
	}

	cert, err := x509.ParseCertificate(rawCerts[0])
	if err != nil {
		return fmt.Errorf("failed to parse certificate: %w", err)
	}

	dnsName := ""
	if len(cert.DNSNames) > 0 {
		dnsName = cert.DNSNames[0]
	}

	opts := cv.buildVerifyOptions(dnsName)

	_, err = cert.Verify(opts)
	if err != nil {
		return fmt.Errorf("certificate verification failed: %w", err)
	}

	return nil
}

func NewOrchestratorClient(caCertPath, baseURL string, shutdownCtx context.Context) (*OrchestratorClient, error) {
	verifier, err := NewCertVerifier(caCertPath, shutdownCtx)
	if err != nil {
		return nil, err
	}

	tlsConfig := &tls.Config{
		InsecureSkipVerify:    true,
		VerifyPeerCertificate: verifier.VerifyPeerCertificate,
	}

	client := &http.Client{
		Transport: &http.Transport{
			TLSClientConfig: tlsConfig,
		},
		Timeout: 30 * time.Second,
	}

	return &OrchestratorClient{
		httpClient: client,
		verifier:   verifier,
		baseURL:    baseURL,
	}, nil
}

func (oc *OrchestratorClient) DrainNode(ctx context.Context, nodeID string) error {
	req, err := http.NewRequestWithContext(ctx, "POST",
		fmt.Sprintf("%s/api/v1/nodes/%s/drain", oc.baseURL, nodeID), nil)
	if err != nil {
		return err
	}

	resp, err := oc.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("drain request failed: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("drain failed with status: %d", resp.StatusCode)
	}

	return nil
}

func (oc *OrchestratorClient) ListPods(ctx context.Context) ([]byte, error) {
	req, err := http.NewRequestWithContext(ctx, "GET",
		fmt.Sprintf("%s/api/v1/pods", oc.baseURL), nil)
	if err != nil {
		return nil, err
	}

	resp, err := oc.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("list pods failed: %w", err)
	}
	defer resp.Body.Close()

	return ioutil.ReadAll(resp.Body)
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())

	client, err := NewOrchestratorClient(
		os.Getenv("CA_CERT_PATH"),
		os.Getenv("ORCHESTRATOR_URL"),
		ctx,
	)
	if err != nil {
		log.Fatalf("Failed to create client: %v", err)
	}

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGTERM, syscall.SIGINT)

	go func() {
		<-sigChan
		log.Println("Received shutdown signal, entering graceful shutdown...")
		cancel()

		// Allow 30s for graceful drain operations
		drainCtx, drainCancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer drainCancel()

		if err := client.DrainNode(drainCtx, os.Getenv("NODE_ID")); err != nil {
			log.Printf("Warning: drain failed: %v", err)
		}

		os.Exit(0)
	}()

	ticker := time.NewTicker(10 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			pods, err := client.ListPods(ctx)
			if err != nil {
				log.Printf("Error listing pods: %v", err)
				continue
			}
			log.Printf("Pods status: %d bytes", len(pods))
		case <-ctx.Done():
			return
		}
	}
}
